    case inactiveAccount
    /**
     * Inactive Subscription
     */
    case inactiveSubscription
    /**
     * Max device numbers reached
     */
    case maxDevicesReached
    /**
     * Device time is off by too much, Zk-nyms use will fail
     */
    case deviceTimeOutOfSync
    /**
