/**
 * Public enum describing the tunnel state
 */

public enum TunnelState: Equatable, Hashable {
    
    /**
     * Tunnel is disconnected and network connectivity is available.
     */
    case disconnected
    /**
     * Tunnel connection is being established.
     */
    case connecting(retryAttempt: UInt32, state: EstablishConnectionState, tunnelType: TunnelType, connectionData: EstablishConnectionData?
    )
    /**
     * Tunnel is connected.
     */
    case connected(connectionData: ConnectionData
    )
    /**
     * Tunnel is disconnecting.
     */
    case disconnecting(afterDisconnect: ActionAfterDisconnect
    )
    /**
     * Tunnel is disconnected due to failure.
     */
    case error(ErrorStateReason
    )
    /**
     * Tunnel is disconnected, network connectivity is unavailable.
     */
    case offline(
        /**
         * Whether tunnel will be reconnected upon gaining the network connectivity.
         */reconnect: Bool
    )





}

#if compiler(>=6)
extension TunnelState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTunnelState: FfiConverterRustBuffer {
    typealias SwiftType = TunnelState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TunnelState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .disconnected
        
        case 2: return .connecting(retryAttempt: try FfiConverterUInt32.read(from: &buf), state: try FfiConverterTypeEstablishConnectionState.read(from: &buf), tunnelType: try FfiConverterTypeTunnelType.read(from: &buf), connectionData: try FfiConverterOptionTypeEstablishConnectionData.read(from: &buf)
        )
        
        case 3: return .connected(connectionData: try FfiConverterTypeConnectionData.read(from: &buf)
        )
        
        case 4: return .disconnecting(afterDisconnect: try FfiConverterTypeActionAfterDisconnect.read(from: &buf)
        )
        
        case 5: return .error(try FfiConverterTypeErrorStateReason.read(from: &buf)
        )
        
        case 6: return .offline(reconnect: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TunnelState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .disconnected:
            writeInt(&buf, Int32(1))
        
        
        case let .connecting(retryAttempt,state,tunnelType,connectionData):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(retryAttempt, into: &buf)
            FfiConverterTypeEstablishConnectionState.write(state, into: &buf)
            FfiConverterTypeTunnelType.write(tunnelType, into: &buf)
            FfiConverterOptionTypeEstablishConnectionData.write(connectionData, into: &buf)
            
        
        case let .connected(connectionData):
            writeInt(&buf, Int32(3))
            FfiConverterTypeConnectionData.write(connectionData, into: &buf)
            
        
        case let .disconnecting(afterDisconnect):
            writeInt(&buf, Int32(4))
            FfiConverterTypeActionAfterDisconnect.write(afterDisconnect, into: &buf)
            
        
        case let .error(v1):
            writeInt(&buf, Int32(5))
            FfiConverterTypeErrorStateReason.write(v1, into: &buf)
            
        
        case let .offline(reconnect):
            writeInt(&buf, Int32(6))
            FfiConverterBool.write(reconnect, into: &buf)
            
        }
    }
}


